import java.util.List;

public class StreamQuiz {
    public static void main(String[] args) {
        long result = List.of("apple", "banana", "cherry", "date")
            .stream()
            .filter(s -> s.length() > 4)
            .map(String::toUpperCase)
            .count();
        System.out.println(result);
    }
}

import java.util.List;
import java.util.Optional;

public class ReduceQuiz {
    public static void main(String[] args) {
        Optional<Integer> result = List.of(3, 1, 4, 1, 5)
            .stream()
            .reduce(Integer::max);
        System.out.println(result.orElse(0));
    }
}

import java.util.List;
import java.util.stream.Stream;

public class FlatMapQuiz {
    public static void main(String[] args) {
        long count = List.of(
            List.of("a", "b"),
            List.of("c"),
            List.of("a", "d", "c")
        ).stream()
            .flatMap(List::stream)
            .distinct()
            .count();
        System.out.println(count);
    }
}
